            use std::os::unix::fs::MetadataExt as _;
            Self {
                size: metadata.len(),
                mtime_nanos,
                ctime_nanos: i128::from(metadata.ctime()) * 1_000_000_000
                    + i128::from(metadata.ctime_nsec()),
                device: metadata.dev(),
                inode: metadata.ino(),
