   319	/// The time column of `ls -l`, in `zone`: `Nov 20 10:43` for a time in
   320	/// the half year before `now_seconds`, `Jan  2  2025` for any other — an
   321	/// older one, or one still to come.
   322	pub fn time_column<Tz>(zone: &Tz, when_seconds: i64, now_seconds: i64) -> String
   323	where
   324	    Tz: chrono::TimeZone,
   325	    Tz::Offset: std::fmt::Display,
