        let temp = tempfile::tempdir().expect("tempdir");
        let path = temp.path().join("file");
        fs::write(&path, b"x").expect("write fixture");
        assert_eq!(permissions_mode(&fs::metadata(path).expect("metadata")), 0);
    }
